local ECSComponent = import("Frame.ECS.ECSComponent")

---@class ActivityCardSkinComponent
local ActivityCardSkinComponent = Class("ActivityCardSkinComponent", ECSComponent)

function ActivityCardSkinComponent:__init()
    self.name = "ActivityCardSkinComponent"
    
end


function ActivityCardSkinComponent:__delete()

end

---初始化
---@param jsonData table
function ActivityCardSkinComponent:Initial(jsonData)
    print("ActivityCardSkinComponent =>" , table.dump(jsonData))
    local ActivityCardSkinDojo  = import("Game.Dojo.ActivityCardSkinDojo")
    local activityData = {}
    local time = os.time() 
    for i, v in ipairs(checkTable(jsonData)) do
        local dojo = ActivityCardSkinDojo.New()
        dojo:Fill(v , time)
        table.insert(activityData, dojo)
    end

    self:SetActivityData(activityData)
    self:SortActivityData()
end

function ActivityCardSkinComponent:SortActivityData()
    ---@type ActivityCardSkinDojo[]
    local activityData = self:GetActivityData()
    table.sort(activityData , function (a , b )
        if a.sort == b.sort then
            if a.startTime == b.startTime  then
                return checkInt(a.id)  > checkInt(b.id)  
            else
                return a.startTime > b.startTime    
            end
        else 
            return a.sort > b.sort    
        end
    end)
end
function ActivityCardSkinComponent:GetIndexByActivityId(activityUuid)
    local index = 1 
    activityUuid = checkInt(activityUuid)
    for k, v in pairs(self:GetActivityData()) do
        if checkInt(v.id) == activityUuid then
            index = k 
            break
        end
    end
    return index
end
---设置活动数据
function ActivityCardSkinComponent:SetActivityData(activityData)
    self._activityData = checkTable(activityData)
end
---@return ActivityCardSkinDojo
function ActivityCardSkinComponent:GetActivityDataByIndex(index)
    return self._activityData[index]
end

function ActivityCardSkinComponent:GetMaxCloseTime()
    local closeTime = 0 
    for k, oneActivity in pairs(self:GetActivityData()) do
        if checkInt(oneActivity.closeTime) >  closeTime then
            closeTime = oneActivity.closeTime
        end
    end
    return closeTime
end
--- 根据活动id 获取活动数据
---@return ActivityCardSkinDojo
function ActivityCardSkinComponent:GetActivityDataById(id)
    id = checkInt(id)
    ---@type ActivityCardSkinDojo[]
    local activityData = self:GetActivityData()
    for k, v in pairs(activityData) do
        if checkInt(v.id) == id then
            return v  
        end
    end
    return nil 
end

function ActivityCardSkinComponent:SetCardSkinRedPoint()
    local num = 0 
    for k, oneActivity in pairs(self:GetActivityData()) do
        if checkInt(oneActivity.redDotHint) == 0 then
            num = 1
            break
        end
    end
    GameUtils.SetRedPointNum(Constants.RedPointConst.MainCardSkin , num)
end


---@return ActivityCardSkinDojo[]
---获取活动数据
function ActivityCardSkinComponent:GetActivityData()
    return self._activityData or {}
end

return ActivityCardSkinComponent